; VERIFIED: IX=parent, C=launch subtype: 1 Viper, 2 Cobra/Python trader, 3 Thargon,
; 4 Thargoid, 5 Sidewinder/Krait (Adder instead of Krait with ship=adder).
; Viper selection bypasses the RNG; all valid choices continue at LaunchSelectedShip.
; The original subtype-2 RNG is correlated with the preceding station gate and always
; chooses Python there. stationrandomlaunchfix=yes repairs the choice in the same 38 bytes.
SelectParentLaunchType:
L_F44A: ; legacy analysis alias; same address, no emitted bytes
IF STATION_RANDOM_LAUNCH_FIX
    INCLUDE "station-random-launch-fix.asm"
ELSE
    LD A,$08                                   ; $F44A: 3E 08
    DEC C                                      ; $F44C: 0D
    JR Z,LaunchSelectedShip                    ; $F44D: 28 21
    CALL NextRandomByte                        ; $F44F: CD 24 ED
    AND $01                                    ; $F452: E6 01
