; VERIFIED: A=selected child type, IX=parent. Create the child at its parent position/orientation.
; Adjust launch orientation only for a non-station parent, then inherit parent hostility.
; On success IX=child, IY=parent and Z is set; NZ reports allocation failure.
LaunchSelectedShip:
L_F470: ; legacy analysis alias; same address, no emitted bytes
    assert SelectParentLaunchType-GameImage = ParentLaunchSelectionStart-$6048
    assert LaunchSelectedShip-GameImage = ParentLaunchSelectionLimit-$6048
    PUSH IX                                    ; $F470: DD E5
    CALL CreateShipAtParent                    ; $F472: CD 81 F3
    POP IY                                     ; $F475: FD E1
    RET NZ                                     ; $F477: C0
