    BIT 2,(IY+$21)                             ; $F47F: FD CB 21 56
    RET Z                                      ; $F483: C8
    SET 2,(IX+$21)                             ; $F484: DD CB 21 D6
    XOR A                                      ; $F488: AF
    RET                                        ; $F489: C9

; VERIFIED: Alternate between two child-orientation adjustments using the toggle at L_F2C9.
; Called for non-station parents only; station launches retain the copied orientation.
