; VERIFIED: Station traffic gate: require instance+$26 bit 2 and EncounterShipCount below four.
; The count comparison leaves carry set for the first NextRandomByte call.
; A calm station branches to TryLaunchStationTrader. A hostile station admits results
; below $24 and normally requests a Viper; mode value 4 uses an extra Thargoid gate.
TryLaunchStationTraffic:
L_F846: ; legacy analysis alias; same address, no emitted bytes
    BIT 2,(IX+$26)                             ; $F846: DD CB 26 56
    JR Z,L_F8A2                                ; $F84A: 28 56
    LD A,(EncounterShipCount)                  ; $F84C: 3A 1B DA
    CP $04                                     ; $F84F: FE 04
    RET NC                                     ; $F851: D0
    CALL NextRandomByte                        ; $F852: CD 24 ED
    BIT 2,(IX+$21)                             ; $F855: DD CB 21 56
    JR Z,TryLaunchStationTrader                ; $F859: 28 16
    CP $24                                     ; $F85B: FE 24
    RET NC                                     ; $F85D: D0
    LD A,(L_A871)                              ; $F85E: 3A 71 A8
    CP $04                                     ; $F861: FE 04
    LD A,$14                                   ; $F863: 3E 14
    JR NZ,DispatchShipEventPreservingParent    ; $F865: 20 0F
    CALL NextRandomByte                        ; $F867: CD 24 ED
    CP $88                                     ; $F86A: FE 88
    RET NC                                     ; $F86C: D0
    LD A,$44                                   ; $F86D: 3E 44
    JR DispatchShipEventPreservingParent       ; $F86F: 18 05

; VERIFIED: Continue with the station gate RNG result in A: only values 0 and 1 permit a trader.
; Event $24 means parent-launch event 4, subtype 2; it is not a ship ID.
TryLaunchStationTrader:
L_F871: ; legacy analysis alias; same address, no emitted bytes
    CP $02                                     ; $F871: FE 02
    RET NC                                     ; $F873: D0
    LD A,$24                                   ; $F874: 3E 24

